#!/bin/sh
# mk-arm64-image.sh — wrap a FreeBSD arm64 kernel ELF as a Linux-style arm64
# "Image" (booti header + flat binary) that `qemu-system-aarch64 -kernel` and
# Firecracker can load. The FreeBSD arm64 ELF itself cannot be loaded by
# either: its p_paddr equals its KERNBASE virtual address (0xffff0000...),
# and QEMU only hands the DTB to non-ELF (Linux-protocol) kernels.
#
# This is a verbatim re-expression of the `${KERNEL_KO}.bin` rule in
# releng/15.0 sys/conf/Makefile.arm64 (objcopy to binary, prepend the header
# blob generated by sys/tools/arm_kernel_boothdr.awk -v hdrtype=v8booti).
# Kernel support is already compiled in by std.arm64 (options LINUX_BOOT_ABI).
# Evidence: docs/SMOLFIRE-A64-FEASIBILITY.md.
#
# Usage: mk-arm64-image.sh KERNEL_ELF OUT_IMAGE
#   KERNEL_ELF  the buildkernel kernel.full (needs the symbol table:
#               kernbase/_start/_end are read from it)
# Env (all optional): OBJCOPY NM AWK ARM_BOOTHDR_AWK
#
# SPDX-License-Identifier: Apache-2.0
set -eu

K=${1:?usage: mk-arm64-image.sh KERNEL_ELF OUT_IMAGE}
OUT=${2:?usage: mk-arm64-image.sh KERNEL_ELF OUT_IMAGE}
OBJCOPY=${OBJCOPY:-objcopy}
NM=${NM:-nm}
AWK=${AWK:-awk}
HDR_AWK=${ARM_BOOTHDR_AWK:-/usr/src/sys/tools/arm_kernel_boothdr.awk}

[ -r "$K" ] || { echo "mk-arm64-image: kernel not readable: $K" >&2; exit 1; }
[ -r "$HDR_AWK" ] || { echo "mk-arm64-image: header generator missing: $HDR_AWK" >&2; exit 1; }

rm -f "$OUT.temp" "$OUT.hdr"
# Strip ARM mapping symbols ($a/$d/$t/$x) like the upstream rule does.
"$OBJCOPY" --wildcard --strip-symbol='$[adtx]*' --output-target=binary "$K" "$OUT.temp"
# arm_kernel_boothdr.awk does its hex->number math in awk doubles (53-bit
# mantissa). FreeBSD arm64 kernbase is 0xffff000000000000 (~2^64), where the
# double spacing is 2048 bytes: an _end/_start that is not 2 KiB-aligned is
# silently rounded (verified identical on mawk, gawk and one-true-awk, see
# docs/SMOLFIRE-A64-FEASIBILITY.md). A rounded _start would corrupt the
# header's `b _start`. So hand the awk script offsets relative to a small
# synthetic kernbase (RB): every value is < 2^53 and therefore exact, and
# the header is identical to what an exact-arithmetic awk would produce.
# 64-bit hex is split as <top 4 digits><low 12 digits> because sh's $((0x..))
# saturates above INT64_MAX.
RB=0000010000000000
syms=$("$NM" "$K" | while read -r a _t n; do
    case "$n" in kernbase|_start|_end) printf '%s %s\n' "$a" "$n" ;; esac
done)
# `if`, not `[ ] && echo`: a false test as the LAST loop command would make the
# substitution fail (rc 1) under set -e whenever kernbase is not the last symbol
# (e.g. an address-sorted `nm -n`, where kernbase comes first).
kb=$(printf '%s\n' "$syms" | while read -r a n; do if [ "$n" = kernbase ]; then echo "$a"; fi; done)
if [ -n "$kb" ]; then
    khi=${kb%????????????}
    klo=${kb#????}
    synth=$(printf '%s\n' "$syms" | while read -r a n; do
        [ "$n" = kernbase ] && continue
        [ "${a%????????????}" = "$khi" ] \
            || { echo "mk-arm64-image: $n ($a) is outside kernbase ($kb) 48-bit window" >&2; exit 1; }
        off=$(( 0x${a#????} - 0x$klo ))
        [ "$off" -ge 0 ] || { echo "mk-arm64-image: $n below kernbase" >&2; exit 1; }
        printf '%016x T %s\n' $(( 0x$RB + off )) "$n"
    done) || exit 1
    synth="$RB A kernbase
$synth"
else
    synth=""    # no kernbase: let the awk script report the missing symbol
fi
printf '%s\n' "$synth" | LC_ALL=C "$AWK" -f "$HDR_AWK" -v hdrtype=v8booti > "$OUT.hdr"
cat "$OUT.hdr" "$OUT.temp" > "$OUT"
rm -f "$OUT.temp" "$OUT.hdr"

# Fail loud: the header must carry the arm64 Image magic ("ARM\x64" at
# offset 56) and the first word must be an A64 unconditional branch (0x14).
magic=$(od -An -tx1 -j56 -N4 "$OUT" | tr -d ' \n')
[ "$magic" = 41524d64 ] \
    || { echo "mk-arm64-image: bad Image magic '$magic' in $OUT" >&2; exit 1; }
top=$(od -An -tx1 -j3 -N1 "$OUT" | tr -d ' \n')
[ "$top" = 14 ] \
    || { echo "mk-arm64-image: first word is not a branch (top byte '$top')" >&2; exit 1; }
echo "mk-arm64-image: $OUT $(wc -c < "$OUT") bytes"
